1	"use client";
2	
3	import Link from "next/link";
4	import { useState } from "react";
5	import {
6	  Sheet,
7	  SheetContent,
8	  SheetHeader,
9	  SheetTitle,
10	} from "@/components/ui/sheet";
11	import { NAV_ITEMS, CTA_NAV } from "@/lib/constants/navigation";
12	import type { NavItem } from "@/types/navigation";
13	
14	/*
15	  Mobile nav (.nav-23-menu at max-width 767px):
16	  - Background: #082753 (Webflow navy)
17	  - Nav links: color #fff, border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0
18	  - Dropdown arrow: color #21cfff
19	  - .nav-23-dropdown-toggle: justify-content space-between, padding 12px 0
20	  Sheet replaces Webflow's native overlay — same colour palette, same structure.
21	*/
22	
23	function ChevronDownIcon({ rotated }: { rotated: boolean }) {
24	  return (
25	    <svg
26	      xmlns="http://www.w3.org/2000/svg"
27	      width="16"
28	      height="16"
29	      viewBox="0 0 24 24"
30	      fill="none"
31	      style={{
32	        color: "#21cfff",
33	        transform: rotated ? "rotate(180deg)" : "rotate(0deg)",
34	        transition: "transform 0.2s ease",
35	        flexShrink: 0,
36	      }}
37	    >
38	      <path
39	        d="M11.9997 13.1714L16.9495 8.22168L18.3637 9.63589L11.9997 15.9999L5.63574 9.63589L7.04996 8.22168L11.9997 13.1714Z"
40	        fill="currentColor"
41	      />
42	    </svg>
43	  );
44	}
45	
46	function MobileNavGroup({
47	  item,
48	  onNavigate,
49	}: {
50	  item: NavItem;
51	  onNavigate: () => void;
52	}) {
53	  const [expanded, setExpanded] = useState(false);
54	
55	  const rowBorder: React.CSSProperties = {
56	    borderBottom: "1px solid rgba(255,255,255,0.04)",
57	  };
58	
59	  if (!item.children) {
60	    return (
61	      /* .nav-23-link at 767px: color #fff, border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0 */
62	      <Link
63	        href={item.href}
64	        onClick={onNavigate}
65	        style={{
66	          display: "flex",
67	          alignItems: "center",
68	          justifyContent: "flex-start",
69	          padding: "12px 0",
70	          fontSize: "15px",
71	          fontWeight: 500,
72	          color: "#fff",
73	          textDecoration: "none",
74	          ...rowBorder,
75	        }}
76	      >
77	        {item.label}
78	      </Link>
79	    );
80	  }
81	
82	  return (
83	    <div style={rowBorder}>
84	      {/* .nav-23-dropdown-toggle at 767px: justify-content space-between, padding 12px 0 */}
85	      <button
86	        type="button"
87	        onClick={() => setExpanded(!expanded)}
88	        style={{
89	          display: "flex",
90	          width: "100%",
91	          alignItems: "center",
92	          justifyContent: "space-between",
93	          padding: "12px 0",
94	          fontSize: "15px",
95	          fontWeight: 500,
96	          color: "#fff",
97	          background: "none",
98	          border: "none",
99	          cursor: "pointer",
100	        }}
101	      >
102	        {item.label}
103	        <ChevronDownIcon rotated={expanded} />
104	      </button>
105	
106	      {expanded && (
107	        /* .nav-23-dropdown-list.w--open at 767px: position static, padding-top 4px, padding-bottom 4px */
108	        <div
109	          style={{
110	            display: "flex",
111	            flexDirection: "column",
112	            paddingTop: "4px",
113	            paddingBottom: "8px",
114	          }}
115	        >
116	          {item.children.map((child) => {
117	            const comingSoonBadge = child.comingSoon ? (
118	              /* .header-comingsoon-badge */
119	              <span
120	                style={{
121	                  color: "#1890ff",
122	                  backgroundColor: "#e6f7ff",
123	                  border: "1px solid #91d5ff",
124	                  borderRadius: "4px",
125	                  padding: "3px 6px",
126	                  fontSize: "9px",
127	                  fontWeight: 700,
128	                  lineHeight: "1em",
129	                  display: "inline-flex",
130	                  alignItems: "center",
131	                  marginLeft: "6px",
132	                  whiteSpace: "nowrap",
133	                }}
134	              >
135	                Coming Soon
136	              </span>
137	            ) : null;
138	
139	            const innerContent = (
140	              <span style={{ display: "flex", alignItems: "center" }}>
141	                <span
142	                  style={{
143	                    fontSize: "14px",
144	                    fontWeight: 500,
145	                    color: "rgba(255,255,255,0.9)",
146	                  }}
147	                >
148	                  {child.label}
149	                </span>
150	                {comingSoonBadge}
151	              </span>
152	            );
153	
154	            const itemStyle: React.CSSProperties = {
155	              display: "flex",
156	              alignItems: "center",
157	              borderRadius: "8px",
158	              padding: "10px 12px",
159	              textDecoration: "none",
160	              transition: "background-color 0.15s",
161	            };
162	
163	            if (child.comingSoon) {
164	              return (
165	                <div
166	                  key={child.label}
167	                  style={{ ...itemStyle, opacity: 0.5, cursor: "default" }}
168	                >
169	                  {innerContent}
170	                </div>
171	              );
172	            }
173	
174	            if (child.external) {
175	              return (
176	                <a
177	                  key={child.label}
178	                  href={child.href}
179	                  target="_blank"
180	                  rel="noopener noreferrer"
181	                  onClick={onNavigate}
182	                  style={itemStyle}
183	                  onMouseEnter={(e) => {
184	                    e.currentTarget.style.backgroundColor = "rgba(255,255,255,0.05)";
185	                  }}
186	                  onMouseLeave={(e) => {
187	                    e.currentTarget.style.backgroundColor = "transparent";
188	                  }}
189	                >
190	                  {innerContent}
191	                </a>
192	              );
193	            }
194	
195	            return (
196	              <Link
197	                key={child.label}
198	                href={child.href}
199	                onClick={onNavigate}
200	                style={itemStyle}
201	                onMouseEnter={(e) => {
202	                  e.currentTarget.style.backgroundColor = "rgba(255,255,255,0.05)";
203	                }}
204	                onMouseLeave={(e) => {
205	                  e.currentTarget.style.backgroundColor = "transparent";
206	                }}
207	              >
208	                {innerContent}
209	              </Link>
210	            );
211	          })}
212	        </div>
213	      )}
214	    </div>
215	  );
216	}
217	
218	export function MobileNav({
219	  open,
220	  onClose,
221	}: {
222	  open: boolean;
223	  onClose: () => void;
224	}) {
225	  return (
226	    <Sheet open={open} onOpenChange={onClose}>
227	      {/* .nav-23-menu at 767px: bg #082753 (dark navy), flex col */}
228	      <SheetContent
229	        side="right"
230	        style={{
231	          width: "300px",
232	          backgroundColor: "#082753",
233	          borderLeft: "1px solid rgba(255,255,255,0.08)",
234	          display: "flex",
235	          flexDirection: "column",
236	          padding: 0,
237	        }}
238	      >
239	        {/* Header row */}
240	        <SheetHeader
241	          style={{
242	            padding: "16px",
243	            borderBottom: "1px solid rgba(255,255,255,0.08)",
244	          }}
245	        >
246	          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
247	            <SheetTitle style={{ fontSize: "18px", fontWeight: 700, color: "#fff" }}>
248	              Boldteq
249	            </SheetTitle>
250	          </div>
251	        </SheetHeader>
252	
253	        {/* Nav links — .nav-23-menu at 767px: padding 10px 4% */}
254	        <div
255	          style={{
256	            display: "flex",
257	            flexDirection: "column",
258	            overflowY: "auto",
259	            padding: "10px 4%",
260	            flex: 1,
261	          }}
262	        >
263	          {NAV_ITEMS.map((item) => (
264	            <MobileNavGroup
265	              key={item.label}
266	              item={item}
267	              onNavigate={onClose}
268	            />
269	          ))}
270	        </div>
271	
272	        {/* CTA buttons at bottom */}
273	        <div
274	          style={{
275	            marginTop: "auto",
276	            padding: "16px",
277	            borderTop: "1px solid rgba(255,255,255,0.08)",
278	            display: "flex",
279	            flexDirection: "column",
280	            gap: "12px",
281	          }}
282	        >
283	          {/* Login — .button-secondary-large adapted for dark bg */}
284	          <a
285	            href={CTA_NAV[0].href}
286	            target="_blank"
287	            rel="noopener noreferrer"
288	            onClick={onClose}
289	            style={{
290	              display: "flex",
291	              width: "100%",
292	              alignItems: "center",
293	              justifyContent: "center",
294	              borderRadius: "10px",
295	              border: "1px solid rgba(255,255,255,0.3)",
296	              padding: "10px 20px",
297	              fontSize: "13px",
298	              fontWeight: 700,
299	              color: "#fff",
300	              textDecoration: "none",
301	              transition: "background-color 0.2s",
302	            }}
303	          >
304	            {CTA_NAV[0].label}
305	          </a>
306	
307	          {/* Schedule Demo — .btn-primary */}
308	          <Link
