1	"use client";
2	
3	import { motion } from "framer-motion";
4	
5	type Direction = "up" | "down" | "left" | "right";
6	
7	const directionOffsets: Record<Direction, { x: number; y: number }> = {
8	  up: { x: 0, y: 40 },
9	  down: { x: 0, y: -40 },
10	  left: { x: 40, y: 0 },
11	  right: { x: -40, y: 0 },
12	};
13	
14	export function ScrollReveal({
15	  children,
16	  direction = "up",
17	  delay = 0,
18	  duration = 0.5,
19	  className,
20	}: {
21	  children: React.ReactNode;
22	  direction?: Direction;
23	  delay?: number;
24	  duration?: number;
25	  className?: string;
26	}) {
27	  const offset = directionOffsets[direction];
28	
29	  return (
30	    <motion.div
31	      initial={{ opacity: 0, x: offset.x, y: offset.y }}
32	      whileInView={{ opacity: 1, x: 0, y: 0 }}
33	      viewport={{ once: true, margin: "-100px" }}
34	      transition={{ duration, delay, ease: "easeOut" }}
35	      className={className}
36	    >
37	      {children}
38	    </motion.div>
39	  );
40	}
